/**
 * The CLI's generated interface table (`src/ifaces.json`, regenerated by its `gen:ifaces`) holds
 * the CLI's and the server package's modules, and no shipped plugin's CLI module.
 *
 * - Given the CLI's program reaches browser-automation's `./cli` sources (through the generated
 *   module list), the table carries none of that module's classes or interfaces: the module boots
 *   against its own table (`cli-ifaces.json`), folded into the CLI's with the CLI's entries
 *   winning, so a copy here would stand in for the module's own.
 */
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import table from "../src/ifaces.json" with { type: "json" };

interface Table {
  ifaces: Record<string, unknown>;
  modules: Record<string, unknown>;
}

const shipped = JSON.parse(
  readFileSync(
    new URL("../../../plugins/browser-automation/cli-ifaces.json", import.meta.url),
    "utf8",
  ),
) as Table;

describe("the CLI's interface table", () => {
  it("carries none of a shipped plugin's CLI module, though the CLI compiles it in", () => {
    const host = table as unknown as Table;
    expect(Object.keys(shipped.modules).length).toBeGreaterThan(0);
    expect(Object.keys(shipped.modules).filter((name) => name in host.modules)).toEqual([]);
    expect(Object.keys(host.ifaces).filter((key) => key.startsWith("@penguinharness/"))).toEqual(
      [],
    );
  });
});
